tests.code:
if (!senpDecision) {
    console.log('  Skipping — only runs for Flipkart SELFEMP with a gstin sent');
    this.skip();
}
this.timeout(30000);
const omni1Row = await CommonAPI.getOmniNodeRow(app_id, 'OMNI_1');
CommonAPI.printOmniDecisionPanel('OMNI_1', omni1Row);
const omni1Gst = CommonAPI.extractGstFromOmniInput(omni1Row.input);
const karza = await CommonAPI.fetchKarzaGst(app_id, panNumber, sentEmployment.gstin);
CommonAPI.printOmniGstPanel('OMNI_1', omni1Gst, karza.gst);
addContext(this, { title: 'OMNI_1 — full OUTPUT (raw)', value: omni1Row.output });
addContext(this, { title: 'OMNI_1 — full INPUT (raw)', value: omni1Row.input });
addContext(this, { title: 'OMNI_1 — DECISION / REJECT_REASON (output)', value: { found: omni1Row.found, decision: omni1Row.decision, rejectReason: omni1Row.rejectReason, message: omni1Row.message } });
addContext(this, { title: 'OMNI_1 — GST (input) vs Karza soft-pull', value: { omni1Gst, karzaGst: karza.gst } });
// OMNI_PRE/OMNI_POST only exist once the app progresses past OMNI_1 (i.e. approved) — best-effort.
for (const segment of ['OMNI_PRE', 'OMNI_POST']) {
    const row = await CommonAPI.getOmniNodeRow(app_id, segment, { retries: 2, intervalMs: 2000 });
    CommonAPI.printOmniDecisionPanel(segment, row);
    const gst = CommonAPI.extractGstFromOmniInput(row.input);
    CommonAPI.printOmniGstPanel(segment, gst, karza.gst);
    addContext(this, { title: `${segment} — full OUTPUT (raw)`, value: row.output });
    addContext(this, { title: `${segment} — full INPUT (raw)`, value: row.input });
    addContext(this, { title: `${segment} — DECISION / REJECT_REASON (output)`, value: { found: row.found, decision: row.decision, rejectReason: row.rejectReason, message: row.message } });
    addContext(this, { title: `${segment} — GST (input) vs Karza soft-pull`, value: { gst, karzaGst: karza.gst } });
}

