}
this.timeout(30000);
const profileRes = await CommonAPI.getcustomerProfile(app_id);
const customerProfile = profileRes?.body?.response ?? null;
if (!customerProfile) {
    console.log('  Info: customer profile could not be fetched — skipping check');
    this.skip();
}
const karza = await CommonAPI.fetchKarzaGst(app_id, panNumber, sentEmployment.gstin);
gstLinkedCheck = CommonAPI.checkGstLinkedAgainstKarza(customerProfile, karza.gst);

