const { body } = bankingres;
const { response } = body;
const hasBureauOffer = response.hasOwnProperty('bureau_offer') && response.bureau_offer !== null;
const hasBankingOffer = response.hasOwnProperty('banking_offer') && response.banking_offer !== null;
// If either bureau_offer or banking_offer is present, verify APR and first_emi_date are not present
if (hasBureauOffer || hasBankingOffer) {
    // Check for annual_pr (APR) in bureau_offer
    if (hasBureauOffer) {
        const hasAnnualPR = response.bureau_offer.hasOwnProperty('annual_pr');
        expect(
            !hasAnnualPR,
            `annual_pr (APR) should NOT be present in bureau_offer when bureau_offer object is present. Found: ${response.bureau_offer.annual_pr}`
        ).to.be.true;
    }
    // Check for annual_pr (APR) in banking_offer
    if (hasBankingOffer) {
        const hasAnnualPR = response.banking_offer.hasOwnProperty('annual_pr');
        expect(
            !hasAnnualPR,
            `annual_pr (APR) should NOT be present in banking_offer when banking_offer object is present. Found: ${response.banking_offer.annual_pr}`
        ).to.be.true;
    }
    // Check for first_emi_date at root level
    const hasFirstEmiDate = response.hasOwnProperty('first_emi_date');
    expect(
        !hasFirstEmiDate,
        `first_emi_date should NOT be present at root level when bureau_offer or banking_offer object is present. Found: ${response.first_emi_date}`
    ).to.be.true;
} else {
    // If neither bureau_offer nor banking_offer is present, skip this test
    console.log('  Info: Neither bureau_offer nor banking_offer is present, skipping validation');
    this.skip();
}

