    // Query underwriting_vendor_transaction_log using application_id as requestId
    const query = 'SELECT * FROM services.underwriting_vendor_transaction_log WHERE requestId = ? ORDER BY id DESC;';
    const params = [app_id];
    const vendorRows = await CommonAPI.runQuery(query, params);

    if (!vendorRows || vendorRows.length === 0) {
        throw new Error('No rows found in underwriting_vendor_transaction_log for requestId: ' + app_id);
    }

    // Extract WorkingStorageSpare from vendor rows input
    let omniPreWorkingStorage = null;
    let omniPostWorkingStorage = null;
    let omniHcWorkingStorage = null;
    for (const vendorRow of vendorRows) {
        const workingStorage = vendorRow.input?.WorkingStorageSpare;
        if (workingStorage) {
            const policySegmentId = vendorRow.input?.['DV-Application']?.['Spare']?.['String01'];
            console.log('policySegmentId:', policySegmentId);
            if (policySegmentId === "OMNI_PRE" && !omniPreWorkingStorage) {
                omniPreWorkingStorage = workingStorage;
                console.log('✅ Assigned OMNI_PRE WorkingStorageSpare');
            } else if (policySegmentId === "OMNI_POST" && !omniPostWorkingStorage) {
                omniPostWorkingStorage = workingStorage;
                console.log('✅ Assigned OMNI_POST WorkingStorageSpare');
            } else if (policySegmentId === "OMNI_HC" && !omniHcWorkingStorage) {
                omniHcWorkingStorage = workingStorage;
                console.log('✅ Assigned OMNI_HC WorkingStorageSpare');
            }
        }
    }


    if (!omniPreWorkingStorage) {
        throw new Error('WorkingStorageSpare not found in OMNI_PRE vendor transaction log output');
    }

    if (!omniPostWorkingStorage) {
        throw new Error('WorkingStorageSpare not found in OMNI_POST vendor transaction log output');
    }

    // Extract values from WorkingStorageSpare
    const omniPreApplicant = omniPreWorkingStorage?.Applicant;
    const omniPreFlag05 = omniPreApplicant?.[0]?.Flag05;
    const omniPreString11 = omniPreApplicant?.[0]?.String11;

    const omniPostApplicant = omniPostWorkingStorage?.Applicant;
    const omniPostFlag05 = omniPostApplicant?.[0]?.Flag05;
    const omniPostString11 = omniPostApplicant?.[0]?.String11;

    // Verify WorkingStorageSpare exists in OMNI_PRE vendor transaction log output
    if (!omniPreWorkingStorage || !omniPreApplicant || !Array.isArray(omniPreApplicant) || omniPreApplicant.length === 0) {
        throw new Error('WorkingStorageSpare.Applicant is missing or empty in OMNI_PRE vendor transaction log output');
    }

    if (omniPreFlag05 === undefined || omniPreFlag05 === null) {
        throw new Error('Flag05 is missing in OMNI_PRE WorkingStorageSpare (vendor transaction log)');
    }

    if (omniPreString11 === undefined || omniPreString11 === null) {
        throw new Error('String11 is missing in OMNI_PRE WorkingStorageSpare (vendor transaction log)');
    }

    // Verify WorkingStorageSpare exists in OMNI_POST vendor transaction log output
    if (!omniPostWorkingStorage || !omniPostApplicant || !Array.isArray(omniPostApplicant) || omniPostApplicant.length === 0) {
        throw new Error('WorkingStorageSpare.Applicant is missing or empty in OMNI_POST vendor transaction log output');
    }

    if (omniPostFlag05 === undefined || omniPostFlag05 === null) {
        throw new Error('Flag05 is missing in OMNI_POST WorkingStorageSpare (vendor transaction log)');
    }

    if (omniPostString11 === undefined || omniPostString11 === null) {
        throw new Error('String11 is missing in OMNI_POST WorkingStorageSpare (vendor transaction log)');
    }

    // Determine expected Flag05 value based on TAG_IDS
    // Flag05 should be "true" if REDI02 is present in TAG_IDS, "false" otherwise (including when TAG_IDS is empty [])
    const hasRedi02 = tagIds.length > 0 && tagIds.includes("REDI02");
    const expectedFlag05 = hasRedi02 ? "true" : "false";

    // Determine expected String11 value (should match TRUST_SCORE)
    // If TRUST_SCORE is "NA", String11 should also be "NA"
    // Otherwise, String11 should match the TRUST_SCORE value
    const expectedString11 = (dsTrustScore === "NA") ? "NA" : String(dsTrustScore);

    // Verify Flag05 in OMNI_PRE
    expect(omniPreFlag05).to.equal(expectedFlag05, 
        `Flag05 mismatch in OMNI_PRE. Expected: ${expectedFlag05} (REDI02 ${hasRedi02 ? 'present' : 'not present'} in TAG_IDS), Got: ${omniPreFlag05}`);

    // Verify String11 in OMNI_PRE (should match TRUST_SCORE, or "NA" if TRUST_SCORE is "NA")
    expect(omniPreString11).to.equal(expectedString11, 
        `String11 mismatch in OMNI_PRE. Expected: ${expectedString11} (TRUST_SCORE: ${dsTrustScore}), Got: ${omniPreString11}`);

    // Verify Flag05 in OMNI_POST
    expect(omniPostFlag05).to.equal(expectedFlag05, 
        `Flag05 mismatch in OMNI_POST. Expected: ${expectedFlag05} (REDI02 ${hasRedi02 ? 'present' : 'not present'} in TAG_IDS), Got: ${omniPostFlag05}`);

    // Verify String11 in OMNI_POST (should match TRUST_SCORE, or "NA" if TRUST_SCORE is "NA")
    expect(omniPostString11).to.equal(expectedString11, 
        `String11 mismatch in OMNI_POST. Expected: ${expectedString11} (TRUST_SCORE: ${dsTrustScore}), Got: ${omniPostString11}`);

    // Verify OMNI_PRE and OMNI_POST have same values
    expect(omniPreFlag05).to.equal(omniPostFlag05, 
        `Flag05 mismatch between OMNI_PRE and OMNI_POST. OMNI_PRE: ${omniPreFlag05}, OMNI_POST: ${omniPostFlag05}`);

    expect(omniPreString11).to.equal(omniPostString11, 
        `String11 mismatch between OMNI_PRE and OMNI_POST. OMNI_PRE: ${omniPreString11}, OMNI_POST: ${omniPostString11}`);

    // Verify String09 (sms_epfo) in OMNI_HC, OMNI_PRE and OMNI_POST
    const omniHcApplicant = omniHcWorkingStorage?.Applicant;
    const omniHcString09 = omniHcApplicant?.[0]?.String09;
    const omniPreString09 = omniPreApplicant?.[0]?.String09;
    const omniPostString09 = omniPostApplicant?.[0]?.String09;
    const smsEpfoFromPayload = cres?.PayLoad?.sms_epfo;
    const expectedString09 = smsEpfoFromPayload === true ? '1' : '0';
    if (omniHcWorkingStorage) {
        expect(omniHcString09).to.equal(expectedString09,
            `String09 mismatch in OMNI_HC. Expected: ${expectedString09} (sms_epfo=${smsEpfoFromPayload}), Got: ${omniHcString09}`);
        console.log(`✅ OMNI_HC String09(sms_epfo): ${omniHcString09}`);
    } else {
        console.log('ℹ️  OMNI_HC vendor row not found — skipping String09 check for OMNI_HC');
    }
    expect(omniPreString09).to.equal(expectedString09,
        `String09 mismatch in OMNI_PRE. Expected: ${expectedString09} (sms_epfo=${smsEpfoFromPayload}), Got: ${omniPreString09}`);
    expect(omniPostString09).to.equal(expectedString09,
        `String09 mismatch in OMNI_POST. Expected: ${expectedString09} (sms_epfo=${smsEpfoFromPayload}), Got: ${omniPostString09}`);
    console.log(`✅ Verified WorkingStorageSpare. Flag05: ${omniPreFlag05}, String11: ${omniPreString11}, String09 — HC: ${omniHcString09}, PRE: ${omniPreString09}, POST: ${omniPostString09}`);
    if (omniHcWorkingStorage) {
        attachLabeledResponseToContext(this, 'OMNI_HC — WorkingStorageSpare (vendor log)', omniHcWorkingStorage);
    }
    attachLabeledResponseToContext(this, 'OMNI_PRE — WorkingStorageSpare (vendor log)', omniPreWorkingStorage);
    attachLabeledResponseToContext(this, 'OMNI_POST — WorkingStorageSpare (vendor log)', omniPostWorkingStorage);
} catch (error) {
    console.error('Error verifying WorkingStorageSpare in OMNI_PRE and OMNI_POST:', error);
    throw error;
}

