this.timeout(75000); // 1 min poll + buffer
const pollIntervalMs = 5000;
const maxWaitMs = 60000;
const start = Date.now();
let lastRes;
while (true) {
    lastRes = await CommonAPI.pennyStatus(app_id, pennytxnid);
    attachInitResponseToContext(this, lastRes);
    const body = lastRes.body;
    const responseStatus = body?.response?.status;
    // Stop on any known terminal response (Completed, Retry, error, failure)
    if (body?.status === 'error' || body?.status === 'failure') break;
    if (responseStatus === 'Completed' || responseStatus === 'Retry') break;
    // Unknown/no response — keep polling until timeout
    if (Date.now() - start >= maxWaitMs) break;
    await new Promise(r => setTimeout(r, pollIntervalMs));
}
res = lastRes;

expect(res.body).to.not.be.empty;
expect(res.body.status).equals('success');
expect(res.body.statusCode).equals(200);
expect(res.body.response.status).equals('Completed');
